const b=$json.body||$json;
let message=String(b.message||'').trim();
if(!message)throw new Error('message e obrigatoria.');
if(/[ÃÂ]/.test(message))message=Buffer.from(message,'latin1').toString('utf8');
const text=message.toLocaleLowerCase('pt-BR');
const pad=n=>String(n).padStart(2,'0');
const action=/\b(cancel\w*|desmarc\w*)\b/.test(text)?'cancel':/\b(reagend\w*|remarc\w*|adi\w*)\b/.test(text)?'reschedule':'schedule';
const useNext=/(pr.{0,3}xim[oa].*(hor.{0,3}rio|slot)|melhor hor.{0,3}rio|pr.{0,3}xima janela)/.test(text)||Boolean(b.use_next_slot);
let messagePlatform=null;
for(const [pattern,value] of [[/\b(instagram|insta)\b/,'instagram'],[/\bfacebook\b/,'facebook'],[/\blinkedin\b/,'linkedin'],[/\b(tiktok|tik tok)\b/,'tiktok']]){if(pattern.test(text)){messagePlatform=value;break;}}
const payloadPlatform=b.platform==null||String(b.platform).trim()===''?null:String(b.platform).trim().toLowerCase();
let daypart=null;
if(/alm.*o/.test(text))daypart='lunch';else if(/manh/.test(text))daypart='morning';else if(/\btarde\b/.test(text))daypart='afternoon';else if(/fim do dia|entardecer/.test(text))daypart='evening';else if(/\bnoite\b/.test(text))daypart='night';
let targetDate=b.target_date?String(b.target_date):null,targetTime=b.target_time?String(b.target_time):null,relativeExpression=null;
const exact=text.match(/(\d{1,2})h(?:(\d{2}))?\b|(?:[aà]s|para|pelas?)\s*(\d{1,2})(?::(\d{2}))?\b/);
if(!targetTime&&exact){const h=Number(exact[1]||exact[3]),m=Number(exact[2]||exact[4]||0);if(h<24&&m<60)targetTime=`${pad(h)}:${pad(m)}:00`;}
const ymd=text.match(/\b(20\d{2})-(\d{2})-(\d{2})\b/),dmy=text.match(/\b(\d{1,2})[\/.-](\d{1,2})(?:[\/.-](20\d{2}))?\b/);
const reference=new Date(b.reference_now||Date.now());
const fmt=d=>`${d.getUTCFullYear()}-${pad(d.getUTCMonth()+1)}-${pad(d.getUTCDate())}`;
if(!targetDate&&ymd)targetDate=`${ymd[1]}-${ymd[2]}-${ymd[3]}`;else if(!targetDate&&dmy){let d=new Date(Date.UTC(Number(dmy[3]||reference.getUTCFullYear()),Number(dmy[2])-1,Number(dmy[1])));targetDate=fmt(d);}
if(!targetDate&&/depois de amanh[aã]/.test(text))relativeExpression='day_after_tomorrow';
else if(!targetDate&&/amanh[aã]/.test(text))relativeExpression='tomorrow';
else if(!targetDate&&/\bhoje\b/.test(text))relativeExpression='today';
const weekdays={domingo:0,segunda:1,terca:2,'terça':2,quarta:3,quinta:4,sexta:5,sabado:6,'sábado':6};
if(!targetDate&&!relativeExpression){for(const [word,dow] of Object.entries(weekdays)){if(text.includes(word)){relativeExpression=`weekday_${dow}`;break;}}}
const external=String(b.external_message_id||`schedule-${Date.now()}-${Math.random().toString(36).slice(2,9)}`);
const source=String(b.source||'conversation').toLowerCase();
const schedule_request={requested:true,payload_platform:payloadPlatform,message_platform:messagePlatform,date_expression:targetDate,relative_expression:relativeExpression,exact_time:targetTime,daypart,use_next_slot:useNext,reference_now:b.reference_now||null,context_timezone:b.timezone||b.context_timezone||null};
return [{json:{channel:String(b.channel||'webhook'),sender_id:String(b.sender_id||'demo-user'),content_id:String(b.content_id||''),message,external_message_id:external,action,payload_platform:payloadPlatform,source,target_date:targetDate,target_time:targetTime,use_next_slot:useNext,requested_version_id:b.version_id||b.requested_version_id||null,relative_expression:relativeExpression,reference_now:b.reference_now||null,context_timezone:b.timezone||b.context_timezone||null,schedule_request}}];
